def transform2(g):
    # find frame: bounding box of 3s
    pts=[(i,j) for i in range(len(g)) for j in range(len(g[0])) if g[i][j]==3]
    r0=min(p[0] for p in pts); r1=max(p[0] for p in pts)
    c0=min(p[1] for p in pts); c1=max(p[1] for p in pts)
    # seed: 3-cell not on frame border
    seed=None
    for i in range(r0+1,r1):
        for j in range(c0+1,c1):
            if g[i][j]==3: seed=(i,j)
    out=[row[:] for row in g]
    for i in range(r0+1,r1):
        for j in range(c0+1,c1):
            if (i,j)==seed: continue
            d=max(abs(i-seed[0]),abs(j-seed[1]))
            out[i][j]=4 if d%2 else 2
    return out

